export type AlgoNodeKind = 'root' | 'question' | 'algorithm' | 'gain' | 'outcome';

export interface AlgoNode {
  id: string;
  label: string;
  labelZh: string;
  kind: AlgoNodeKind;
  category: string;
  time: string;
  space: string;
  ds: string;
  desc: string;
  /** question nodes: 'yesno' 是非題 | 'choice' 選擇題 */
  qtype: '' | 'yesno' | 'choice';
  /** question nodes: which step of 拆解問題 (1 需要優化嗎 / 2 了解資料 / 3 問題要什麼) */
  stage: number;
  /** algorithm leaves: id of the algorithm this leaf stands for (same algorithm can be several leaves) */
  ref: string;
}

/** kind = the kind of the edge's target node */
export interface AlgoEdge {
  from: string;
  to: string;
  reason: string;
  kind: AlgoNodeKind;
  /** answer to the question (是 / 否 / option text) */
  answer: string;
}

export interface AlgoNext {
  from: string;
  to: string;
  reason: string;
}

