/** 遇到新限制時可以繼續往哪裡走（顯示在詳細面板） */
export const algoNext: AlgoNext[] = [
  {
    "from": "linear-search",
    "to": "binary-search",
    "reason": "資料已經排序且支援隨機存取 → 每次排除一半。"
  },
  {
    "from": "linear-search",
    "to": "hash-lookup",
    "reason": "需要大量精確查找 → 以額外空間換取 O(1) 預期查找。"
  },
  {
    "from": "linear-search",
    "to": "heap-priority-queue",
    "reason": "每次都要線性掃描找極值 → 改用 Heap，O(log n)。"
  },
  {
    "from": "linear-search",
    "to": "monotonic-stack",
    "reason": "對每個元素往左右掃描找更大值 O(n²) → 單調堆疊 O(n)。"
  },
  {
    "from": "linear-search",
    "to": "kmp",
    "reason": "在文字中逐一比對模式字串 O(nm) 太慢。"
  },
  {
    "from": "binary-search",
    "to": "interpolation-search",
    "reason": "數值分布均勻 → 用內插估算位置，平均 O(log log n)。"
  },
  {
    "from": "binary-search",
    "to": "binary-search-on-answer",
    "reason": "要找的不是某個元素，而是「最小可行的答案」。"
  },
  {
    "from": "hash-lookup",
    "to": "trie",
    "reason": "需要依照前綴查詢，Hash 做不到。"
  },
  {
    "from": "bubble-sort",
    "to": "insertion-sort",
    "reason": "資料接近排序完成 → 插入排序可提早停止比較。"
  },
  {
    "from": "bubble-sort",
    "to": "merge-sort",
    "reason": "資料量增加，O(n²) 過慢 → 需要穩定 O(n log n)。"
  },
  {
    "from": "bubble-sort",
    "to": "quick-sort",
    "reason": "資料量增加，O(n²) 過慢 → 平均 O(n log n)。"
  },
  {
    "from": "insertion-sort",
    "to": "merge-sort",
    "reason": "資料量變大且不再接近排序 → 穩定 O(n log n)。"
  },
  {
    "from": "merge-sort",
    "to": "counting-sort",
    "reason": "鍵值是小範圍整數 → 不用比較，O(n + k)。"
  },
  {
    "from": "quick-sort",
    "to": "heap-sort",
    "reason": "無法接受 O(n²) 最壞情況，又要 O(1) 空間。"
  },
  {
    "from": "quick-sort",
    "to": "counting-sort",
    "reason": "鍵值是小範圍整數 → 不用比較，O(n + k)。"
  },
  {
    "from": "two-pointers",
    "to": "sliding-window",
    "reason": "兩指標之間維護的是連續區間 → 增量更新答案。"
  },
  {
    "from": "sliding-window",
    "to": "monotonic-queue",
    "reason": "需要即時取得視窗內的極值 → 單調佇列 O(1) 查詢。"
  },
  {
    "from": "prefix-sum",
    "to": "fenwick-tree",
    "reason": "陣列會被修改，重建前綴和 O(n) 太慢 → O(log n) 更新。"
  },
  {
    "from": "fenwick-tree",
    "to": "segment-tree",
    "reason": "需要 min / max 或區間修改 → 線段樹。"
  },
  {
    "from": "bfs",
    "to": "dijkstra",
    "reason": "邊開始有（非負）權重，層數不等於距離。"
  },
  {
    "from": "dijkstra",
    "to": "bellman-ford",
    "reason": "出現負權重邊，貪婪選擇不再正確。"
  },
  {
    "from": "dijkstra",
    "to": "floyd-warshall",
    "reason": "需要所有點對最短路徑，且 V 很小。"
  },
  {
    "from": "kruskal",
    "to": "prim",
    "reason": "圖非常稠密 (E ≈ V²)，排序所有邊太貴。"
  },
  {
    "from": "dfs",
    "to": "disjoint-set-union",
    "reason": "邊不斷加入，需要反覆查詢連通性。"
  },
  {
    "from": "dfs",
    "to": "backtracking",
    "reason": "需要列舉所有路徑或組合，不合法時退回。"
  },
  {
    "from": "dfs",
    "to": "topological-sort",
    "reason": "需要依照依賴關係排出處理順序。"
  },
  {
    "from": "greedy",
    "to": "dp-tabulation",
    "reason": "找到反例，貪婪不保證最佳 → 動態規劃。"
  },
  {
    "from": "dp-memoization",
    "to": "dp-tabulation",
    "reason": "狀態有明確依賴順序 → Bottom-up，避免遞迴堆疊。"
  },
  {
    "from": "backtracking",
    "to": "dp-memoization",
    "reason": "回溯時反覆遇到相同狀態 → 快取結果。"
  },
  {
    "from": "backtracking",
    "to": "branch-and-bound",
    "reason": "目標是最佳解且可估界 → 剪掉不可能更好的分支。"
  },
  {
    "from": "divide-and-conquer",
    "to": "dp-memoization",
    "reason": "切出來的子問題其實會重複 → 動態規劃（記憶化）。"
  },
  {
    "from": "recursion",
    "to": "dp-memoization",
    "reason": "遞迴過程存在重複子問題 → 快取狀態結果。"
  },
  {
    "from": "recursion",
    "to": "backtracking",
    "reason": "需要列舉所有候選解並可剪枝。"
  },
  {
    "from": "recursion",
    "to": "divide-and-conquer",
    "reason": "子問題互不重疊，可以各自解完再合併。"
  },
  {
    "from": "brute-force",
    "to": "branch-and-bound",
    "reason": "能估計上下界 → 剪掉不可能更好的分支。"
  },
  {
    "from": "brute-force",
    "to": "dp-memoization",
    "reason": "列舉時同一狀態重複出現 → 動態規劃。"
  }
];

